"""First-principles presentation notes and independently checked examples.

Dry sensible-energy models. No new CFD or Lean proof is generated here.
"""
import json,math
from pathlib import Path
from build import STUDY,CP,GAS,PA
OUT=STUDY/'results/formulas'

def calculate():
    source=json.loads((STUDY.parent/'pass-by-study/source-input.json').read_text())
    tc=json.loads((STUDY/'results/campaign-plan.json').read_text())['source_c'];ta=30.;delta=ta-tc
    rho=PA/(GAS*(tc+273.15));area=.28*.04;u=.077/(rho*4*area)
    power=source['active_motors']*source['shaft_work_per_motor_w'];mass=source['active_motors']*source['mass_per_motor_kg_s']
    motor=source['inlet_c']-power/(mass*CP);p1=PA+source['inlet_pressure_bar_g']*1e5;t2s=(source['inlet_c']+273.15)*(PA/p1)**(2/7)
    result=dict(assumptions=dict(ambient_c=ta,cold_source_c=tc,cp_j_kg_k=CP,gas_j_kg_k=GAS,pressure_pa=PA,dry_air=True,constant_cp=True,hardware_validated=False,new_lean_proof=False),flows=[dict(g_s=g,power_w=g/1000*CP*delta,injected_g_at_10s=g*10,ideal_total_mixed_g_s_at_6k=g*delta/6) for g in [2,27,52,77]],vortex_example=dict(g_s=2,source_c=5,ambient_c=30,power_w=.002*CP*25,status='Illustration using reported 5 C nozzle and assumed 2 g/s; no measured thermal field'),mixing=dict(source_deficit_k=delta,minimum_cold_mass_fraction_for_6k=6/delta,maximum_warm_to_cold_ratio_at_6k=delta/6-1,examples=[dict(warm_to_cold_ratio=e,drop_k=delta/(1+e),mixed_c=ta-delta/(1+e)) for e in [0,1,4,9]]),nozzle=dict(total_g_s=77,outlets=4,area_each_m2=area,density_kg_m3=rho,exit_speed_m_s=u,static_temperature_to_stagnation_difference_k=u*u/(2*CP),travel_at_exit_speed_s=[.2/u,.5/u],hydraulic_diameter_m=2*.28*.04/(.28+.04),Richardson_exit=9.81*delta/(ta+273.15)*(2*.28*.04/(.28+.04))/(u*u)),source=dict(total_mass_kg_s=mass,shaft_power_w=power,inlet_c=source['inlet_c'],motor_exhaust_c=motor,cold_path_ua_w_k=source['cold_path_ua_w_k'],delivered_c=ta+(motor-ta)*math.exp(-source['cold_path_ua_w_k']/(mass*CP)),ideal_isentropic_exhaust_c=t2s-273.15,inferred_adiabatic_temperature_efficiency=(source['inlet_c']-motor)/(source['inlet_c']+273.15-t2s),source_pressure_bar_g=7,motor_pressure_bar_g=6.3,available_pressure_head_bar=7-6.3),hose_example=dict(ua_w_k=1,ambient_c=30,inlet_c=5,status='Illustrative fixed UA, not measured hardware',outlets=[dict(g_s=g,outlet_c=30+(5-30)*math.exp(-1/(g/1000*CP))) for g in [2,77]]),warmup_example=dict(tau_s=.5,initial_deficit_k=delta,time_to_6k_s=.5*math.log(delta/6),status='Hypothetical well-mixed source-off zone; tau is assumed, not a CFD or measurement result'))
    # Conservation and limiting cases, not a physical validation claim.
    checks=[]
    def check(name,v):
        assert v,name;checks.append(name)
    check('Four-motor first law agrees with source boundary',abs(result['source']['delivered_c']-tc)<1e-10)
    check('Thermal source rate linear in mass at fixed temperatures',abs(result['flows'][-1]['power_w']/result['flows'][0]['power_w']-77/2)<1e-12)
    fine=json.loads((STUDY/'results/m77_n4_wide_opposed_fine.json').read_text())['inputs']
    check('Continuity matches declared exit-speed calculation',abs(u-fine['exit_speed_m_s'])<1e-10)
    check('Native inlet speed agrees within gas-constant rounding',abs(u/fine['source_mean_speed_m_s']-1)<1e-4)
    e=result['mixing']['maximum_warm_to_cold_ratio_at_6k'];check('Entrainment boundary gives exactly 6 K',abs(delta/(1+e)-6)<1e-12)
    check('No ambient entrainment retains source temperature',abs((ta-delta)-tc)<1e-12)
    check('Four warm masses to one cold mass misses 6 K',delta/5<6)
    check('Mixing energy conserved',all(abs((r['mixed_c']*(1+r['warm_to_cold_ratio'])-(tc+r['warm_to_cold_ratio']*ta)))<1e-10 for r in result['mixing']['examples']))
    check('Same hose UA warms the small flow more',result['hose_example']['outlets'][0]['outlet_c']>result['hose_example']['outlets'][1]['outlet_c'])
    check('Zero UA preserves duct inlet temperature',30+(5-30)*math.exp(0)==5)
    check('Source-off threshold inversion is exact',abs(delta*math.exp(-result['warmup_example']['time_to_6k_s']/.5)-6)<1e-12)
    check('Nozzle static-temperature change is negligible at selected speed',result['nozzle']['static_temperature_to_stagnation_difference_k']<.001)
    check('Rated-work source lies above isentropic limit',t2s-273.15<motor<40)
    result['references']=[dict(title='MIT: control-volume conservation and stagnation temperature',url='https://web.mit.edu/16.unified/www/FALL/thermodynamics/notes/node19.html'),dict(title='MIT: ideal-gas heat capacity and reversible adiabatic expansion',url='https://web.mit.edu/16.unified/www/FALL/thermodynamics/notes/node18.html')]
    return result,dict(status='passed',checks=len(checks),items=checks,scope='Algebra, limits and agreement with current inputs. No hardware, turbulence, transient-zone or new Lean validation.')

def build():
    OUT.mkdir(exist_ok=True);r,audit=calculate();(OUT/'calculations.json').write_text(json.dumps(r,indent=2));(OUT/'validation.json').write_text(json.dumps(audit,indent=2))
    d=r['mixing']['source_deficit_k'];e=r['mixing']['maximum_warm_to_cold_ratio_at_6k'];u=r['nozzle']['exit_speed_m_s'];m=r['source'];hose=r['hose_example']['outlets']
    cards=[
     ('1 · Mass flow supplies cooling power','Q̇ = ṁ c<sub>p</sub> (T<sub>a</sub> − T<sub>c</sub>)<br>M<sub>injected</sub> = ṁ t','More g/s means more cooling energy each second. Grams are stored mass; g/s is the delivery rate.',f'At 0.96°C supply: 2 g/s ≈58 W; 77 g/s ≈2.25 kW. A 10 s spray injects 20 g or 770 g.','Reported vortex case: 2 g/s at 5°C against 30°C has only about 50 W sensible capacity. This explains a limited budget, not the exact cause of the reported test failure. Not all source air reaches the target. Ideal cooling capacity is not skin heat removal.'),
     ('2 · The nozzle sets delivery','U<sub>0</sub> = ṁ / (ρ n A<sub>e</sub>)<br>J ≈ ṁ U<sub>0</sub>','Area, shape, count and aim change reach, spread and mixing. Small passages add backpressure; oversized outlets can lose useful momentum.',f'77 g/s through four 280 × 40 mm exits → {u:.2f} m/s. The nozzle redistributes the cold source; it does not add refrigeration.',f'Uniform equal exits and near-atmospheric pressure are assumed. J is exit momentum flux; pressure thrust must be added for an overpressured jet. At this speed, kinetic recovery changes static temperature by only {r["nozzle"]["static_temperature_to_stagnation_difference_k"]:.4f} K. Re = ρ U D_h / μ; Ri ≈ g(ΔT/T_a)D_h/U². These screen mixing/transition and buoyancy; they do not determine the target temperature by themselves. Exit-speed travel estimate 20–50 cm: {r["nozzle"]["travel_at_exit_speed_s"][0]:.2f}–{r["nozzle"]["travel_at_exit_speed_s"][1]:.2f} s. Real velocity changes along the jet.'),
     ('3 · Warm-air mixing removes the temperature drop','T<sub>mix</sub> = (ṁ<sub>c</sub>T<sub>c</sub> + ṁ<sub>a</sub>T<sub>a</sub>) / (ṁ<sub>c</sub> + ṁ<sub>a</sub>)<br>ΔT = (T<sub>a</sub> − T<sub>c</sub>) / (1 + E)','E = entrained warm mass / captured cold-source mass. Nozzle engineering aims to limit dilution while covering the target.',f'For >6°C drop with 30°C ambient and 0.96°C source: E < {e:.2f}, or cold-source fraction >{100*6/d:.1f}%. At E = 4, drop is only {d/5:.2f}°C.','This is an adiabatic dry-air mixing balance with common constant cp. It applies to local captured flows, not automatically to the producer’s entire flow. For a finite mixed parcel, replace mass rates with masses. At fixed E, more flow changes power, not mixture temperature. Actual E changes with geometry, flow, gravity and wind; CFD or measurement must establish it.'),
     ('4 · Pressure enables expansion and pays flow losses','T<sub>2s</sub> / T<sub>1</sub> = (p<sub>2</sub> / p<sub>1</sub>)<sup>(γ−1)/γ</sup><br>Δp<sub>loss</sub> ≈ (f L/D + ΣK) ρ U²/2','An expander lowers stagnation temperature by extracting work. A regulator is approximately isenthalpic; for ideal air, throttling alone gives no recovered bulk-temperature drop.',f'7 bar gauge supply − 6.3 bar at running motors leaves only {m["available_pressure_head_bar"]:.1f} bar for treatment, hoses, valves and regulation.','Use kelvin and absolute pressure in the expansion relation; γ≈1.4. The ideal isentropic value is a limit, not the actual vane-motor exhaust. Actual adiabatic T2≈T1−ηs(T1−T2s). The first law at the loaded point gives Tmotor≈Tin−(Wshaft−Qinto_air)/(ṁcp), neglecting changes in kinetic/potential energy. Four ×840 W at 77.6 g/s and 40°C gives −3.04°C before the assumed path warming. Higher exhaust backpressure reduces expansion ratio. Darcy loss uses local density and low-Mach segment assumptions; large pressure changes require compressible analysis. Pressure, source temperature and flow are coupled in hardware.'),
     ('5 · Hoses warm small flows more','T<sub>out</sub> = T<sub>a</sub> + (T<sub>in</sub> − T<sub>a</sub>) e<sup>−UA/(ṁc<sub>p</sub>)</sup>','Longer or poorly insulated cold paths add heat before release. Small mass flow has less heat capacity per second.',f'Illustration only: 5°C entering air, 30°C surroundings, UA = 1 W/K → {hose[0]["outlet_c"]:.1f}°C at 2 g/s; {hose[1]["outlet_c"]:.1f}°C at 77 g/s.','UA is overall thermal conductance in W/K, not area alone. The expression assumes steady wall conditions and constant properties; first-pulse cooldown and sunlight are extra effects. This describes a duct heat exchanger. Open-jet warming is mainly ambient mixing, with no fixed duct-wall UA. The real cold-path UA has not been measured.'),
     ('6 · Rapid warming has no universal time constant','ΔT(t) = ΔT<sub>0</sub> e<sup>−t/τ</sup><br>τ = M c<sub>p</sub> / (ṁ<sub>exchange</sub> c<sub>p</sub> + UA)','This is a well-mixed, source-off zone model. Smaller zones and stronger warm-air exchange warm faster. Geometry, wind and gravity change that exchange.',f'A 0.5 s lifetime cannot be assumed from the exponential shape. Colder starting air still increases the available temperature margin.','M is resident zone mass, not mass flow. Ambient and properties are constant; exchange and UA are assumed fixed. For ΔT0>6 K, time above 6 K is t6=τ ln(ΔT0/6). Hypothetical example: a zone initially at 0.96°C, ambient 30°C and assumed τ=0.5 s crosses 6 K after 0.79 s. This is not a measured or CFD lifetime. A continuous spray replenishes the zone; its energy balance includes the source term. The saved CFD ends at 10 s ON and contains no source-off decay.')
    ]
    body=''.join(f'<article class="formula-card"><h3>{title}</h3><div class="formula-equation">{eq}</div><p>{why}</p><p class="formula-example">{example}</p><details class="compact-details"><summary>Assumptions / derivation</summary><p>{limits}</p></details></article>' for title,eq,why,example,limits in cards)
    table=''.join(f'<tr><td>{f["g_s"]}</td><td>{f["power_w"]:.0f}</td><td>{f["injected_g_at_10s"]}</td></tr>' for f in r['flows'])
    section='''<section class="card" id="formulas"><div class="section-head"><h2>Why these parameters?</h2><a href="formulas/first-principles.txt" download>Presentation notes ↓</a></div><p class="compact-context">Dry-air first principles · examples are calculations, not new CFD</p><p class="formula-takeaway">Mass flow supplies cooling power. Pressure supports expansion and flow. The nozzle controls where that cooling reaches and how much warm air mixes in.</p><div class="formula-grid">'''+body+'''</div><details class="compact-details"><summary>Current-model power table and symbols</summary><div class="table"><table><thead><tr><th>Flow g/s</th><th>Sensible budget W</th><th>Injected mass in 10 s · g</th></tr></thead><tbody>'''+table+'''</tbody></table></div><p class="note">Fixed 0.9593°C source / 30°C ambient; cp = 1006 J/(kg·K). ṁ: kg/s; divide g/s by 1000. Tc: cold source; Ta: ambient. ρ: local density; n: outlet count; Ae: area per outlet. J: momentum flux; E: warm/cold captured-mass ratio. M: resident zone mass; UA: W/K; τ: seconds. Actual source temperature changes with motor load, heat pickup and pressure. Source budget and mixed-flow limits are not resident cooled mass/volume.</p></details><details class="compact-details"><summary>Source and steady-zone balance</summary><div class="formula-equation">M c<sub>p</sub> dT/dt = ṁ<sub>c</sub>c<sub>p</sub>(T<sub>c</sub>−T) + ṁ<sub>exchange</sub>c<sub>p</sub>(T<sub>a</sub>−T) + UA(T<sub>a</sub>−T) + Q̇<sub>load</sub></div><p class="note">Well-mixed fixed-mass zone; outflow balances total inflow. Source term stays active while spraying. Positive Qload adds heat. CFD resolves a spatial field instead of assuming this uniform zone.</p></details><details class="compact-details"><summary>What a person feels</summary><div class="formula-equation">Q̇<sub>skin,conv</sub> ≈ h A<sub>skin</sub>(T<sub>skin</sub> − T<sub>local air</sub>)</div><p class="note">Local air temperature, speed, exposed skin area and exposure time control convective heat removal. Humidity affects evaporation; sunlight adds radiant heat. Source cooling power and air-temperature drop alone do not establish comfort. The CFD has no person or skin model.</p></details><div class="links"><a href="formulas/calculations.json">Worked calculations</a><a href="formulas/validation.json">Algebra checks</a><a href="source-provenance.json">Source assumptions</a><a href="../../motor-seat-study/FIRST-PRINCIPLES.txt">Project first principles</a><a href="../../formal-model/AAThermo.lean">Existing Lean source</a></div><p class="note">Foundation: <a href="https://web.mit.edu/16.unified/www/FALL/thermodynamics/notes/node19.html">MIT control-volume conservation</a> · <a href="https://web.mit.edu/16.unified/www/FALL/thermodynamics/notes/node18.html">MIT ideal-gas thermodynamics</a>. Mixing, duct and zone equations above follow from the stated energy balances.</p><p class="note">No new Lean proof or hardware validation. See existing proof hypotheses before using a theorem as a physical claim.</p></section>'''
    notes=['FIRST PRINCIPLES / OUTDOOR AIR DELIVERY','Dry ideal-air / constant-cp approximations. No new CFD or Lean proof.','']
    from lxml import html
    for title,eq,why,example,limits in cards:notes.extend([title,html.fragment_fromstring('<div>'+eq.replace('<br>','\n')+'</div>').text_content(),why,example,limits,''])
    notes.extend(['FOUNDATIONS']+[ref['title']+' — '+ref['url'] for ref in r['references']])
    (OUT/'first-principles.txt').write_text('\n'.join(notes));(OUT/'section.html').write_text(section)
    print(json.dumps(audit));return section

if __name__=='__main__':build()
